PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','staff','admin')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS properties (id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('buy','rent')), property_type TEXT NOT NULL, price_minor INTEGER NOT NULL CHECK(price_minor>=0), bedrooms INTEGER NOT NULL CHECK(bedrooms>=0), bathrooms INTEGER NOT NULL CHECK(bathrooms>=0), parking INTEGER NOT NULL CHECK(parking>=0), locality TEXT NOT NULL, summary TEXT NOT NULL, description TEXT NOT NULL, publication_state TEXT NOT NULL CHECK(publication_state IN ('draft','published','archived')), transaction_status TEXT NOT NULL, media TEXT NOT NULL DEFAULT '[]', features TEXT NOT NULL DEFAULT '[]', version INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, available_date TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, CHECK((mode='buy' AND transaction_status IN ('available','under_offer','sold','withdrawn')) OR (mode='rent' AND transaction_status IN ('available','application_pending','leased','withdrawn'))));
CREATE TABLE IF NOT EXISTS saves (user_id TEXT NOT NULL REFERENCES users(id), property_id TEXT NOT NULL REFERENCES properties(id), PRIMARY KEY(user_id,property_id));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), customer_id TEXT NOT NULL REFERENCES users(id), stage TEXT NOT NULL DEFAULT 'new', assigned_to TEXT REFERENCES users(id), follow_up TEXT NOT NULL DEFAULT '', due_at TEXT NOT NULL DEFAULT '', blocked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(property_id,customer_id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, client_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(sender_id,client_key));
CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reads (conversation_id TEXT REFERENCES conversations(id), user_id TEXT REFERENCES users(id), read_at TEXT NOT NULL, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS slots (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), starts_at TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), cancelled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inspections (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), customer_id TEXT NOT NULL REFERENCES users(id), slot_id TEXT REFERENCES slots(id), proposed TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('requested','confirmed','completed','cancelled')), reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS active_inspection ON inspections(customer_id,slot_id) WHERE status IN ('requested','confirmed');
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, subject_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outcomes (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), status TEXT NOT NULL, reversed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS public_properties ON properties(publication_state,transaction_status,mode,price_minor);
CREATE INDEX IF NOT EXISTS conversation_messages ON messages(conversation_id,created_at);
PRAGMA user_version=1;
